inline unsigned crc(const std::vector<unsigned char>&s){unsigned state=0u;auto update=[&](const unsigned char*p){auto c=~state;for(unsigned k=0;k<4u;++k){c^=p[k];for(unsigned bit=0;bit<8u;++bit)c=(c>>1u)^((c&1u)?0xedb88320u:0u);}state=~c;};unsigned p=0;for(;p+4u<=s.size();p+=4u)update(s.data()+p);if(p<s.size()){unsigned char tail[4]{};unsigned n=unsigned(s.size())-p;for(unsigned k=0;k<n;++k)tail[k]=s[p+k];tail[n]=static_cast<unsigned char>(n);for(unsigned k=n+1u;k<4u;++k)tail[k]=tail[0];update(tail);}return state;}
using RGB=std::array<unsigned,3>;
inline RGB half_value(RGB rgb){const auto v=*std::max_element(rgb.begin(),rgb.end()),lo=*std::min_element(rgb.begin(),rgb.end()),d=v-lo;unsigned h=0,s=0;if(v&&d){s=255u*d/v;if(s){const unsigned r=(v-rgb[0])*255u/d,g=(v-rgb[1])*255u/d,bb=(v-rgb[2])*255u/d;const unsigned hue=v==rgb[0]?(lo==rgb[1]?1280u+bb:256u-g):v==rgb[1]?(lo==rgb[2]?256u+r:768u-bb):(lo==rgb[0]?768u+g:1280u-r);h=(hue/6u)&255u;}}const auto value=v/2u,sector=(6u*h/255u)%6u,fraction=6u*h%255u;const unsigned p=value*(255u-s)/255u,q=value*(255u-fraction*s/255u)/255u,t=value*(255u-(255u-fraction)*s/255u)/255u;switch(sector){case 0:return{value,t,p};case 1:return{q,value,p};case 2:return{p,value,t};case 3:return{p,q,value};case 4:return{t,p,value};default:return{value,p,q};}}
