 Proof prove(const b::HeapAdapter&h)const{need(h.addresses.size()==58u&&h.live().size()==58u,"1087 complete58 LIVE owned allocations");Proof p;const auto sizes=allocation_sizes();for(const auto&block:h.live()){const auto id=block.ordinal;need(id<58u&&block.bytes==sizes[id]&&block.address==h.addresses[id],"1087 exact rounded LIVE extent inventory");const auto relation=h.identify(block.address,block.bytes);need(relation.ordinal==id&&relation.offset==0u,"1087 immutable whole LIVE ordinal proof");p.address[id]=block.address;p.size[id]=block.bytes;}return p;}
 unsigned reference(const b::HeapAdapter&h,unsigned group,unsigned ref)const{return ref==0u?h.addresses[29u*group+3u]:ref==1u?h.addresses[29u*group+2u]:h.addresses[29u*group+1u]+0x17cu;}
 std::vector<unsigned char>block(unsigned id,const b::HeapAdapter&h)const{auto v=b::fresh(id,allocation_sizes()[id]);const auto group=id/29u,local=id%29u,first=29u*group;if(local==0u){for(unsigned k=0;k<768u;++k)v[k]=static_cast<unsigned char>(source_byte(k,4u+group)*4u);}else if(local==1u){for(unsigned off=4u;off<=0x17cu;off+=4u)b::word(v,off,0u);b::word(v,0u,0x788f70u);b::word(v,4u,1u);b::word(v,0x16cu,1u);b::word(v,0x170u,h.addresses[first+3u]);b::word(v,0x174u,h.addresses[first+3u]);b::word(v,0x178u,h.addresses[first+2u]);for(unsigned j=0;j<25u;++j)b::word(v,descriptors[j].field,h.addresses[first+4u+j]);}else if(local==2u||local==3u){v[0]=0u;for(unsigned n=1;n<256u;++n)v[n]=static_cast<unsigned char>(nearest(local==2u?half_value(rgb(n,group)):rgb(n,group),group));}else{const auto&d=descriptors[local-4u];b::word(v,0u,d.vptr);b::word(v,4u,reference(h,group,d.ref4));if(d.bytes==12u)b::word(v,8u,reference(h,group,d.ref8));}return v;}
