struct Observation{std::vector<b::Event>events;std::vector<std::vector<unsigned char>>live,prefree;std::vector<unsigned char>image,arena;unsigned scalar{},heap_bytes{},prefree_bytes{},normalizations{};};
inline Observation verify(const World&w,b::HeapAdapter&h,unsigned eax,const ra2::platform::x87::Image&fp,const std::vector<unsigned char>&bi,const std::vector<unsigned char>&ba,const unsigned char*image,const unsigned char*arena){need(h.events().size()==58u&&h.snapshots.empty()&&h.allocation_flags.size()==58u,"1087 exact58targetalloc/no frees/events");const auto p=w.prove(h);Observation o;o.events=h.events();
 // EAX is a proven owner-derived integer with AL replaced, NOT an arbitrary pointer.
 need(eax==((p.address[30u]&0xffffff00u)|1u),"1087 complete rawEAX second ownedcontext high24 and actual initializedflag AL1");
 auto expected=ba,ei=bi;constexpr unsigned outputs[]{0xaa8ca8u,0xaa8cacu,0xaa8cb0u,0xaa8b78u};for(unsigned j=0;j<4u;++j){b::word(ei,outputs[j]-0x400000u,w.backing()+j*0x400u);ei[0xaa8cb4u+j-0x400000u]=0u;}for(unsigned group=0;group<2u;++group){b::word(ei,0xaa8bc0u+8u*group-0x400000u,p.address[29u*group]);b::word(ei,0xaa8bc4u+8u*group-0x400000u,p.address[29u*group+1u]);b::word(expected,w.registry()-w.base+4u*(w.c.index+group),p.address[29u*group+1u]);}b::word(ei,0x439490u,w.c.index+2u);need(std::equal(expected.begin(),expected.end(),arena)&&std::equal(ei.begin(),ei.end(),image),"1087 independent full image/arena/name/cache/registry/output graph oracle");o.image=ei;o.arena=expected;
 for(unsigned group=0;group<2u;++group){for(unsigned local=0;local<2u;++local){const auto off=0xaa8bc0u+8u*group+4u*local-0x400000u;b::word(o.image,off,p.token(b::readword(o.image,off),29u*group+local));++o.normalizations;}const auto off=w.registry()-w.base+4u*(w.c.index+group);b::word(o.arena,off,p.token(b::readword(o.arena,off),29u*group+1u));++o.normalizations;}
 for(unsigned id=0;id<58u;++id){const auto&e=o.events[id];need(e.kind==b::Event::Kind::allocate&&e.ordinal==id&&e.size==p.size[id]&&e.address==p.address[id]&&e.result==p.address[id]&&h.allocation_flags[id]==0u,"1087 actual ordered allocation/rawresult/flags");std::vector<unsigned char>bytes(reinterpret_cast<const unsigned char*>(std::uintptr_t(p.address[id])),reinterpret_cast<const unsigned char*>(std::uintptr_t(p.address[id]))+p.size[id]);need(bytes==w.block(id,h),"1087 independent complete palette/colorconversion/nearest/ties/descriptors/roundedpadding oracle");o.heap_bytes+=p.size[id];const auto group=id/29u,local=id%29u,first=29u*group;if(local==1u){for(unsigned off:{0x170u,0x174u}){b::word(bytes,off,p.token(b::readword(bytes,off),first+3u));++o.normalizations;}b::word(bytes,0x178u,p.token(b::readword(bytes,0x178u),first+2u));++o.normalizations;for(unsigned j=0;j<25u;++j){const auto off=descriptors[j].field;b::word(bytes,off,p.token(b::readword(bytes,off),first+4u+j));++o.normalizations;}}else if(local>=4u){const auto&d=descriptors[local-4u];for(unsigned off=4u;off<d.bytes;off+=4u){const auto ref=off==4u?d.ref4:d.ref8;const auto ordinal=first+(ref==0u?3u:ref==1u?2u:1u),offset=ref==2u?0x17cu:0u;b::word(bytes,off,p.token(b::readword(bytes,off),ordinal,offset));++o.normalizations;}}o.live.push_back(std::move(bytes));}
 // Raw equation above proved all32 bits; abstract only that known owner-derived scalar.
 o.scalar=0xd0870001u+30u*0x10000u;++o.normalizations;need(ra2::platform::x87::same_numeric(fp,w.expected_fp()),"1087 complete unchanged numeric x87");return o;}
inline void compare(const Observation&a,const Observation&d){need(a.scalar==d.scalar&&a.image==d.image&&a.arena==d.arena&&a.live==d.live&&a.events.size()==d.events.size(),"1087 paired complete outputs/heap/image/arena/ownedderivedreturn");for(unsigned id=0;id<58u;++id){const auto&x=a.events[id],&y=d.events[id];need(x.kind==y.kind&&x.ordinal==y.ordinal&&x.size==y.size,"1087 paired real58allocationevents");}}
